public static double GetToolbarHeight(
    double rowHeight,
    double descriptionHeight,
    bool showDescription,
    bool showHorizontalScrollbar,
    double scrollbarHeight)
{
    return rowHeight
         + (showDescription ? descriptionHeight : 0)
         + (showHorizontalScrollbar ? scrollbarHeight : 0);
}

